CREATE TABLE IF NOT EXISTS cms_theme_settings(id INTEGER PRIMARY KEY CHECK(id=1),theme_key TEXT NOT NULL DEFAULT 'vazin-default',style_tokens_json TEXT NOT NULL DEFAULT '{}',template_parts_json TEXT NOT NULL DEFAULT '{}',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO cms_theme_settings(id,theme_key) VALUES(1,'vazin-default');
CREATE TABLE IF NOT EXISTS cms_template_assignments(id INTEGER PRIMARY KEY AUTOINCREMENT,scope_type TEXT NOT NULL CHECK(scope_type IN('global','content_type','taxonomy','page')),scope_key TEXT NOT NULL,template_key TEXT NOT NULL,priority INTEGER NOT NULL DEFAULT 100,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(scope_type,scope_key));
CREATE TABLE IF NOT EXISTS cms_site_templates(id INTEGER PRIMARY KEY AUTOINCREMENT,template_key TEXT NOT NULL UNIQUE,label TEXT NOT NULL,template_type TEXT NOT NULL CHECK(template_type IN('front-page','home','single','page','archive','taxonomy','search','404','part')),block_document TEXT NOT NULL DEFAULT '',block_schema_version INTEGER NOT NULL DEFAULT 1,is_system INTEGER NOT NULL DEFAULT 0 CHECK(is_system IN(0,1)),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT OR IGNORE INTO schema_migrations(version) VALUES('10.14.0');